public class UsuariosController {
 private final VBox area; private final UsuarioDAO dao=new UsuarioDAO(); private final SessionManager session=SessionManager.getInstance(); private TableView<Usuario> table; private TextField search; private Pager pager; private List<Usuario> pagerData=List.of();
 public UsuariosController(VBox area){this.area=area;}
 public void mostrar(){area.getChildren().clear();Label t=new Label("Gestión de Usuarios");t.setFont(Font.font("Inter",FontWeight.BOLD,22));Label s=new Label("Solo se muestran usuarios activos. Los inactivos están en la Papelera.");s.getStyleClass().add("muted");area.getChildren().addAll(t,s,tabla());}
 private VBox tabla(){VBox box=new VBox(10);box.setPadding(new Insets(12));box.getStyleClass().add("card");HBox f=new HBox(8);search=new TextField();search.setPromptText("Buscar por nombre, usuario o email...");search.textProperty().addListener((o,a,b)->cargar());HBox.setHgrow(search,Priority.ALWAYS);Button nuevo=new Button("Nuevo");nuevo.setDisable(!session.esAdministrador());nuevo.setOnAction(e->alta());Button info=new Button("Ver información");Button pass=new Button("🔑 Contraseña");Button editar=new Button("Editar");Button papel=new Button(tx("Eliminar","Delete"));f.getChildren().addAll(search,nuevo);box.getChildren().add(f);
  table=new TableView<>();table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY);table.getColumns().add(col(tx("Nombre","Name"),Usuario::nombreProperty));table.getColumns().add(col(tx("Apellido","Surname"),Usuario::apellidoProperty));table.getColumns().add(col(tx("Usuario","User"),Usuario::usuarioProperty));table.getColumns().add(col(tx("Email","Email"),Usuario::emailProperty));table.getColumns().add(col(tx("Rol","Role"),u->new javafx.beans.property.SimpleStringProperty(roleText(u.getRol()))));table.getColumns().add(col(tx("Dependencia","Department"),Usuario::dependenciaProperty));table.getColumns().add(col(tx("Estado","Status"),Usuario::estadoProperty));
  this.pager=new Pager(table,8);
  cargar();
  info.setOnAction(e->{Usuario u=table.getSelectionModel().getSelectedItem();if(u!=null)detalle(u);});editar.setOnAction(e->{Usuario u=table.getSelectionModel().getSelectedItem();if(u!=null)editar(u);});papel.setOnAction(e->{Usuario u=table.getSelectionModel().getSelectedItem();if(u!=null)enviarPapel(u);});pass.setOnAction(e->{Usuario u=table.getSelectionModel().getSelectedItem();if(u!=null)clave(u);});
  HBox actions=new HBox(8,info,editar,pass,papel);editar.setDisable(!session.esAdministrador());pass.setDisable(!session.esAdministrador());papel.setDisable(!session.esAdministrador());box.getChildren().addAll(table,pager.controls(),actions);
  try{List<Usuario> all=dao.buscarUsuarios("","Todos","Activo","Todas");box.getChildren().addAll(metricas(all),recientes(all));}catch(Exception e){error(e.getMessage());}
  VBox.setVgrow(table,Priority.ALWAYS);return box;}
 private HBox metricas(List<Usuario> data){long mes=data.stream().filter(u->isThisMonth(u.getFechaRegistro())).count();long roles=data.stream().map(Usuario::getRol).filter(Objects::nonNull).distinct().count();long dep=data.stream().map(Usuario::getDependencia).filter(v->v!=null&&!v.isBlank()).distinct().count();return metricRow(new String[][]{{tx("Total de usuarios","Total users"),String.valueOf(data.size()),tx("Usuarios registrados","Registered users")},{tx("Nuevos este mes","New this month"),String.valueOf(mes),tx("Durante el mes actual","During current month")},{tx("Roles distintos","Distinct roles"),String.valueOf(roles),tx("Roles configurados","Configured roles")},{tx("Dependencias","Departments"),String.valueOf(dep),tx("Áreas registradas","Registered areas")}});}
 private HBox metricRow(String[][] vals){HBox row=new HBox(15);for(String[]v:vals){VBox c=new VBox(4);c.setMaxWidth(Double.MAX_VALUE);c.setPadding(new Insets(15));c.getStyleClass().add("card-metric");Label a=new Label(v[0]),b=new Label(v[1]),z=new Label(v[2]);a.getStyleClass().add("metric-label");b.getStyleClass().add("metric-value");z.getStyleClass().add("metric-detail");c.getChildren().addAll(a,b,z);row.getChildren().add(c);HBox.setHgrow(c,Priority.ALWAYS);}return row;}
 private VBox recientes(List<Usuario> data){VBox box=new VBox(10);box.getStyleClass().add("card");Label title=new Label("🕒 "+tx("Últimos usuarios registrados","Latest users registered"));title.getStyleClass().add("recent-title");TableView<Usuario> t=new TableView<>();t.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY);t.setFixedCellSize(40);t.setPrefHeight(8*40+38);t.setMinHeight(8*40+38);t.getColumns().add(col(tx("Nombre","Name"),Usuario::nombreProperty));t.getColumns().add(col(tx("Apellido","Surname"),Usuario::apellidoProperty));t.getColumns().add(col(tx("Usuario","User"),Usuario::usuarioProperty));t.getColumns().add(col(tx("Rol","Role"),u->new javafx.beans.property.SimpleStringProperty(roleText(u.getRol()))));List<Usuario> sorted=new ArrayList<>(data);sorted.sort((a,b)->String.valueOf(b.getFechaRegistro()).compareTo(String.valueOf(a.getFechaRegistro())));t.setItems(FXCollections.observableArrayList(sorted.subList(0,Math.min(8,sorted.size()))));box.getChildren().addAll(title,t);return box;}
 private boolean isThisMonth(String value){try{java.time.LocalDate d=java.time.LocalDate.parse(value.substring(0,10));java.time.LocalDate n=java.time.LocalDate.now();return d.getYear()==n.getYear()&&d.getMonthValue()==n.getMonthValue();}catch(Exception e){return false;}}
 private <T> TableColumn<Usuario,T> col(String n,java.util.function.Function<Usuario,javafx.beans.value.ObservableValue<T>> f){TableColumn<Usuario,T> c=new TableColumn<>(n);c.setCellValueFactory(x->f.apply(x.getValue()));return c;}
 private void cargar(){if(table==null)return;try{pagerData = dao.buscarUsuarios(search.getText(),"Todos","Activo","Todas"); pager.setData(pagerData);}catch(Exception e){error(e.getMessage());}}
 private ComboBox<String> dependencias(){List<String>v=new ArrayList<>(List.of("Sistemas","Mesa de Entradas","Turismo","Secretaría de Turismo","Inspección General","Modernización","Tesorería","Administración","Cultura","Deportes","Obras Públicas","Desarrollo Social"));try{String x=com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion("dependencias_extra","");for(String a:x.split("\n"))if(!a.isBlank()&&!v.contains(a.trim()))v.add(a.trim());}catch(Exception ignored){}return new ComboBox<>(FXCollections.observableArrayList(v));}
 private ComboBox<String> emailDomains(){
  List<String> defaults=new ArrayList<>(List.of("@gmail.com","@outlook.com","@hotmail.com","@yahoo.com","@icloud.com","@proton.me","@live.com","@municipalidad.gob.ar","@sannantonio.gob.ar"));
  try{
   String saved=com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion("dominios_email_usuarios","");
   if(saved!=null&&!saved.isBlank()) for(String d:saved.split("\\s*;\\s*")){String x=d.trim();if(!x.isBlank()&&!defaults.contains(x))defaults.add(x);}
  }catch(Exception ignored){}
  return new ComboBox<>(FXCollections.observableArrayList(defaults));
}
 private String combineEmail(TextField local,ComboBox<String>domain){return local.getText().trim()+Objects.toString(domain.getValue(),"");}
 private void splitEmail(String email,TextField local,ComboBox<String>domain){String v=email==null?"":email.trim();int at=v.lastIndexOf('@');if(at>0){local.setText(v.substring(0,at));String suffix=v.substring(at);if(domain.getItems().contains(suffix))domain.setValue(suffix);else{domain.getItems().add(suffix);domain.setValue(suffix);}}else local.setText(v);}
 private void emailInput(TextField local,ComboBox<String>domain){local.setPromptText("usuario");local.setTextFormatter(new TextFormatter<String>(c->{String z=c.getControlNewText();return z.matches("[A-Za-z0-9._%+-]*")?c:null;}));domain.getSelectionModel().selectFirst();}
 private void emailField(GridPane g,TextField local,ComboBox<String>domain,int row){
  Button addDomain=new Button("+");
  addDomain.setMinSize(30,30);addDomain.setPrefSize(30,30);addDomain.setMaxSize(30,30);addDomain.setTooltip(new Tooltip("Añadir dominio de correo"));
  addDomain.setOnAction(e->agregarDominioEmail(domain));
  HBox field=new HBox(6,local,domain,addDomain);field.getStyleClass().add("email-domain-field");addDomain.getStyleClass().add("email-add-domain");HBox.setHgrow(local,Priority.ALWAYS);domain.setPrefWidth(150);field.setMaxWidth(Double.MAX_VALUE);g.add(field,1,row);
} 
private void agregarDominioEmail(ComboBox<String>domain){
  TextInputDialog dialog=new TextInputDialog("@ejemplo.com");
  dialog.setTitle("Nuevo dominio de correo");dialog.setHeaderText("Añadir dominio");dialog.setContentText("Dominio:");
  dialog.showAndWait().ifPresent(valor->{
   String d=valor.trim().toLowerCase();
   if(!d.startsWith("@"))d="@"+d;
   if(!d.matches("@[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\\.[a-z]{2,}")){error("El dominio no tiene un formato válido. Ejemplo: @ejemplo.com");return;}
   if(domain.getItems().contains(d)){domain.setValue(d);return;}
   domain.getItems().add(d);domain.setValue(d);guardarDominiosEmail(domain);
  });
}
private void guardarDominiosEmail(ComboBox<String>domain){
  try{
   String dominios=String.join(";",domain.getItems());
   com.usuarios.database.DatabaseConnection.getInstance().guardarConfiguracion("dominios_email_usuarios",dominios);
  }catch(Exception ignored){}
}
 private void alta(){Dialog<Usuario>d=new Dialog<>();d.setTitle("Nuevo usuario");ButtonType ok=new ButtonType("Guardar",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(ok,ButtonType.CANCEL);GridPane g=grid();TextField nombre=new TextField(),apellido=new TextField(),usuario=new TextField(),email=new TextField();ComboBox<String>dep=dependencias(),emailDomain=emailDomains();DatePicker fecha=new DatePicker();fecha.setDayCellFactory(dp->new DateCell(){@Override public void updateItem(java.time.LocalDate item,boolean empty){super.updateItem(item,empty);setDisable(empty||item.isAfter(java.time.LocalDate.now().minusYears(18)));}});PasswordField pass=new PasswordField();ComboBox<String> rol=new ComboBox<>(FXCollections.observableArrayList(roles()));rol.getSelectionModel().selectFirst();add(g,"Nombre *",nombre,0);add(g,"Apellido *",apellido,1);add(g,"Usuario *",usuario,2);Label emailLabel=new Label("Email *");emailLabel.getStyleClass().add("required");g.add(emailLabel,0,3);emailInput(email,emailDomain);emailField(g,email,emailDomain,3);addComboPlus(g,"Rol *",rol,4,"roles_extra","Nuevo rol");addComboPlus(g,"Dependencia *",dep,5,"dependencias_extra","Nueva dependencia");add(g,"Fecha de nacimiento *",fecha,6);add(g,"Contraseña *",pass,7);d.getDialogPane().setContent(g);styleDialog(d);Button save=(Button)d.getDialogPane().lookupButton(ok);save.setDisable(false);save.addEventFilter(javafx.event.ActionEvent.ACTION,e->{Map<String,String>m=Map.of("nombre",nombre.getText().trim(),"apellido",apellido.getText().trim(),"usuario",usuario.getText().trim(),"email",combineEmail(email,emailDomain),"dependencia",dep.getValue()==null?"":dep.getValue(),"fecha_nacimiento",fecha.getValue()==null?"":fecha.getValue().toString(),"contrasena",pass.getText());List<String>er=validarUsuario(m);if(!er.isEmpty()){e.consume();error("Corrige TODOS estos datos antes de guardar:\n\n• "+String.join("\n• ",er));}});d.setResultConverter(b->{if(b!=ok)return null;Map<String,String>m=Map.of("nombre",nombre.getText().trim(),"apellido",apellido.getText().trim(),"usuario",usuario.getText().trim(),"email",combineEmail(email,emailDomain),"dependencia",dep.getValue()==null?"":dep.getValue(),"fecha_nacimiento",fecha.getValue()==null?"":fecha.getValue().toString(),"contrasena",pass.getText());List<String>er=validarUsuario(m);if(!er.isEmpty()){error(String.join("\n",er));return null;}Usuario nu=new Usuario(0,m.get("nombre"),m.get("usuario"),m.get("email"),rolInterno(rol.getValue()),m.get("dependencia"),"Activo",m.get("contrasena"));nu.setApellido(m.get("apellido"));nu.setFechaNacimiento(m.get("fecha_nacimiento"));return nu;});d.showAndWait().ifPresent(u->ejecutar(()->dao.insertarUsuario(u),"Usuario creado correctamente."));}
 private void editar(Usuario u){if(!session.esAdministrador())return;Dialog<Usuario>d=new Dialog<>();d.setTitle("Editar usuario");ButtonType ok=new ButtonType("Guardar",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(ok,ButtonType.CANCEL);GridPane g=grid();TextField nombre=new TextField(u.getNombre()),apellido=new TextField(u.getApellido()),usuario=new TextField(u.getUsuario()),email=new TextField();ComboBox<String>dep=dependencias(),emailDomain=emailDomains();splitEmail(u.getEmail(),email,emailDomain);dep.setValue(u.getDependencia()); DatePicker fecha=new DatePicker();fecha.setDayCellFactory(dp->new DateCell(){@Override public void updateItem(java.time.LocalDate item,boolean empty){super.updateItem(item,empty);setDisable(empty||item.isAfter(java.time.LocalDate.now().minusYears(18)));}}); try{fecha.setValue(java.time.LocalDate.parse(u.getFechaNacimiento()));}catch(Exception ignored){}ComboBox<String>rol=new ComboBox<>(FXCollections.observableArrayList(roles()));rol.setValue(rolVisible(u.getRol()));add(g,"Nombre *",nombre,0);add(g,"Apellido *",apellido,1);add(g,"Usuario *",usuario,2);Label emailLabel=new Label("Email *");emailLabel.getStyleClass().add("required");g.add(emailLabel,0,3);emailInput(email,emailDomain);emailField(g,email,emailDomain,3);addComboPlus(g,"Rol *",rol,4,"roles_extra","Nuevo rol");addComboPlus(g,"Dependencia *",dep,5,"dependencias_extra","Nueva dependencia");add(g,"Fecha de nacimiento *",fecha,6);d.getDialogPane().setContent(g);styleDialog(d);Button save=(Button)d.getDialogPane().lookupButton(ok);save.addEventFilter(javafx.event.ActionEvent.ACTION,e->{Map<String,String>m=Map.of("nombre",nombre.getText().trim(),"apellido",apellido.getText().trim(),"usuario",usuario.getText().trim(),"email",combineEmail(email,emailDomain),"dependencia",dep.getValue()==null?"":dep.getValue(),"fecha_nacimiento",fecha.getValue()==null?"":fecha.getValue().toString(),"contrasena","");List<String>er=validarUsuario(m);if(!er.isEmpty()){e.consume();error("Corrige TODOS estos datos antes de guardar:\n\n• "+String.join("\n• ",er));}});d.setResultConverter(b->{if(b!=ok)return null;Map<String,String>m=Map.of("nombre",nombre.getText().trim(),"apellido",apellido.getText().trim(),"usuario",usuario.getText().trim(),"email",combineEmail(email,emailDomain),"dependencia",dep.getValue()==null?"":dep.getValue(),"fecha_nacimiento",fecha.getValue()==null?"":fecha.getValue().toString(),"contrasena","");List<String>er=validarUsuario(m);if(!er.isEmpty()){error(String.join("\n",er));return null;}Usuario nu=new Usuario(u.getId(),m.get("nombre"),m.get("usuario"),m.get("email"),rolInterno(rol.getValue()),m.get("dependencia"),"Activo",u.getContrasena(),u.getFechaRegistro());nu.setApellido(m.get("apellido"));nu.setFechaNacimiento(m.get("fecha_nacimiento"));return nu;});d.showAndWait().ifPresent(x->ejecutar(()->dao.actualizarUsuario(x),"Usuario actualizado correctamente."));}
 private String roleText(String r){try{if("en".equals(com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion("idioma","es")))return switch(r){case "Operador"->"Operator";case "Administrador"->"Administrator";default->r;};}catch(Exception ignored){}return r;}
 private String tx(String es,String en){try{return "en".equals(com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion("idioma","es"))?en:es;}catch(Exception e){return es;}}
 private String[] roles(){try{String i=com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion("idioma","es");List<String>base=new ArrayList<>(List.of("Operador","Inspector","Director","Administrador"));String extra=com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion("roles_extra","");for(String x:extra.split("\n"))if(!x.isBlank()&&!base.contains(x.trim()))base.add(x.trim());if("en".equals(i))return base.stream().map(this::roleText).toArray(String[]::new);return base.toArray(String[]::new);}catch(Exception e){return new String[]{"Operador","Inspector","Director","Administrador"};}}
 private String rolVisible(String r){try{String i=com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion("idioma","es");if("en".equals(i))return switch(r){case "Operador"->"Operator";case "Administrador"->"Administrator";default->r;};}catch(Exception ignored){}return r;}
 private String rolInterno(String r){return switch(r){case "Operator"->"Operador";case "Administrator"->"Administrador";default->r;};}
 private List<String>validarUsuario(Map<String,String>m){List<String>e=new ArrayList<>();String x=ValidationUtils.validatePerson("Nombre",m.get("nombre"),ValidationUtils.MAX_NOMBRE);if(x!=null)e.add(x);x=ValidationUtils.validatePerson("Apellido",m.get("apellido"),ValidationUtils.MAX_APELLIDO);if(x!=null)e.add(x);x=ValidationUtils.validateUser(m.get("usuario"));if(x!=null)e.add(x);x=ValidationUtils.validateEmail(m.get("email"));if(x!=null)e.add(x);if(m.getOrDefault("dependencia","").isBlank())e.add("Dependencia es obligatoria.");else if(m.get("dependencia").length()>ValidationUtils.MAX_DEPENDENCIA)e.add("Dependencia supera el máximo de caracteres.");String fecha=m.getOrDefault("fecha_nacimiento","");String fx=ValidationUtils.validateAdult(fecha);if(fx!=null)e.add(fx);if(m.getOrDefault("contrasena","").length()>0&&m.get("contrasena").length()<6)e.add("La contraseña debe tener al menos 6 caracteres.");return e;}
 private void enviarPapel(Usuario u){if(u.getId()==session.getUsuarioActual().getId()){error("No puedes enviar a la papelera el usuario con el que estás conectado.");return;}Alert a=new Alert(Alert.AlertType.CONFIRMATION,tx("¿Eliminar a "+u.getNombre()+"?","Delete "+u.getNombre()+"?"),ButtonType.OK,ButtonType.CANCEL);a.showAndWait().filter(x->x==ButtonType.OK).ifPresent(x->ejecutar(()->dao.enviarAPapelera(u.getId()),tx("Usuario eliminado.","User deleted.")));}
 private void clave(Usuario u){if(!session.esAdministrador()){error("Solo un Administrador puede consultar contraseñas.");return;}String clave=dao.obtenerContrasena(u.getId());Dialog<String>d=new Dialog<>();d.setTitle("Contraseña de usuario");d.setHeaderText("Usuario: "+u.getUsuario());TextField p=new TextField(clave);p.setPrefWidth(280);VBox v=new VBox(10,new Label("Contraseña actual"),p);v.setPadding(new Insets(15));d.getDialogPane().setContent(v);ButtonType cambiar=new ButtonType("Cambiar",ButtonBar.ButtonData.OK_DONE);d.getDialogPane().getButtonTypes().addAll(cambiar,ButtonType.CANCEL);d.setResultConverter(b->b==cambiar?p.getText():null);d.showAndWait().ifPresent(n->{if(!n.equals(clave))ejecutar(()->dao.cambiarContrasena(u.getId(),n),"Contraseña actualizada correctamente.");});}
 private void detalle(Usuario u){Dialog<Void>d=new Dialog<>();d.setTitle("Información");GridPane g=grid();String[][]v={{"Nombre",u.getNombre()},{"Apellido",u.getApellido()},{"Usuario",u.getUsuario()},{"Email",u.getEmail()},{"Rol",u.getRol()},{"Dependencia",u.getDependencia()},{"Nacimiento",u.getFechaNacimiento()},{"Estado",u.getEstado()},{"Registro",u.getFechaRegistro()}};int r=0;for(String[]x:v){g.add(new Label(x[0]),0,r);TextField f=new TextField(x[1]);f.setEditable(false);g.add(f,1,r++);}ScrollPane sp=new ScrollPane(g);sp.setFitToWidth(true);sp.setHbarPolicy(ScrollPane.ScrollBarPolicy.NEVER);sp.setVbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);sp.setPannable(true);d.getDialogPane().setContent(sp);d.getDialogPane().getButtonTypes().add(ButtonType.OK);styleDialog(d);d.showAndWait();}
 private GridPane grid(){GridPane g=new GridPane();g.setHgap(10);g.setVgap(9);g.setPadding(new Insets(12));ColumnConstraints a=new ColumnConstraints();a.setMinWidth(150);ColumnConstraints b=new ColumnConstraints();b.setHgrow(Priority.ALWAYS);g.getColumnConstraints().addAll(a,b);return g;}
 private void requiredMark(Label label,Control c,int min){Runnable r=()->{String v=c instanceof TextInputControl ti?ti.getText():c instanceof DatePicker dp?(dp.getValue()==null?"":dp.getValue().toString()):Objects.toString(((ComboBox<?>)c).getValue(),"");boolean ok=!v.isBlank()&&v.trim().length()>=min;String base=label.getText().replace(" *","");label.setText(ok?base:base+" *");if(ok)label.getStyleClass().remove("required");else if(!label.getStyleClass().contains("required"))label.getStyleClass().add("required");};if(c instanceof TextInputControl ti)ti.textProperty().addListener((o,a,b)->r.run());else if(c instanceof DatePicker dp)dp.valueProperty().addListener((o,a,b)->r.run());else if(c instanceof ComboBox<?> cb)cb.valueProperty().addListener((o,a,b)->r.run());r.run();}
 private void addComboPlus(GridPane g,String label,ComboBox<String>combo,int row,String key,String title){Label x=new Label(label);if(label.endsWith(" *"))x.getStyleClass().add("required");Button plus=new Button("+");plus.getStyleClass().add("email-add-domain");plus.setOnAction(e->{TextInputDialog d=new TextInputDialog();d.setTitle(title);d.setHeaderText(null);d.setContentText("Nombre:");d.showAndWait().ifPresent(v->{String z=v.trim();if(z.isBlank()||combo.getItems().contains(z))return;combo.getItems().add(z);combo.setValue(z);try{String old=com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion(key,"");com.usuarios.database.DatabaseConnection.getInstance().guardarConfiguracion(key,old.isBlank()?z:old+"\n"+z);}catch(Exception ex){error(ex.getMessage());}});});HBox box=new HBox(6,combo,plus);HBox.setHgrow(combo,Priority.ALWAYS);g.add(x,0,row);g.add(box,1,row);}
  private void add(GridPane g,String l,Control c,int r){Label x=new Label(l);if(l.endsWith(" *")){x.getStyleClass().add("required");requiredMark(x,c,l.contains("Nombre")||l.contains("Apellido")?3:l.contains("Contraseña")?6:1);}g.add(x,0,r);g.add(c,1,r);c.setPrefWidth(240);c.setMaxWidth(Double.MAX_VALUE);}
 private void ejecutar(Runnable r,String ok){try{r.run();cargar();NotificationManager.getInstance().mostrarNotificacion(ok,"exito");}catch(RuntimeException e){error(e.getMessage());}}
 private void styleDialog(Dialog<?> d){d.getDialogPane().getStyleClass().add("app-dialog");d.setOnShown(e->{var sc=d.getDialogPane().getScene();if(sc!=null){sc.getStylesheets().add(getClass().getResource("/dashboard.css").toExternalForm());try{if("oscuro".equals(com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion("tema","claro")))sc.getRoot().getStyleClass().add("dark");if("contraste".equals(com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion("accesibilidad","normal")))sc.getRoot().getStyleClass().add("contrast");String a=com.usuarios.database.DatabaseConnection.getInstance().leerConfiguracion("accesibilidad","normal");if(a.equals("Protanopía"))sc.getRoot().getStyleClass().add("protanopia");else if(a.equals("Deuteranopía"))sc.getRoot().getStyleClass().add("deuteranopia");else if(a.equals("Tritanopía"))sc.getRoot().getStyleClass().add("tritanopia");else if(a.equals("Acromatopsia"))sc.getRoot().getStyleClass().add("achromatopsia");}catch(Exception ignored){}}});}
 private static class Pager{private final TableView<Usuario> table;private final int size;private final Button prev=new Button("‹"),next=new Button("›");private final Label info=new Label();private List<Usuario> data=List.of();private int page=0;Pager(TableView<Usuario> t,int s){table=t;size=s;prev.setOnAction(e->{if(page>0){page--;refresh();}});next.setOnAction(e->{if((page+1)*size<data.size()){page++;refresh();}});}void setData(List<Usuario>d){data=d==null?List.of():new ArrayList<>(d);page=0;refresh();}void refresh(){int pages=Math.max(1,(data.size()+size-1)/size);int a=Math.min(page*size,data.size()),b=Math.min(a+size,data.size());table.setItems(FXCollections.observableArrayList(data.subList(a,b)));prev.setDisable(page==0);next.setDisable(page>=pages-1);info.setText((page+1)+" / "+pages+" · "+data.size());}HBox controls(){HBox h=new HBox(8,prev,info,next);h.setAlignment(Pos.CENTER);h.setMaxWidth(Double.MAX_VALUE);h.getStyleClass().add("pager-controls");return h;}}
 private void error(String m){Alert a=new Alert(Alert.AlertType.ERROR,m==null?"Error":m,ButtonType.OK);styleDialog(a);a.showAndWait();}
}
